export const ZERO_DIFFERENCE_ENGINE_SUCCESSOR_ORDER=Object.freeze(["assets/own-payroll-engine.js", "scripts/lib/own-close-snapshot214-installation.mjs", "scripts/lib/own-close-snapshot215-installation.mjs", "scripts/lib/own-m7-native-test-fixture.mjs", "scripts/lib/own-m7-public-schema-batch.mjs", "scripts/lib/own-m7-public-successors213215.mjs", "scripts/lib/own-m5-m7-novelty-positive-profile.mjs", "scripts/lib/own-m7-native-test-connected-fixture.mjs", "scripts/lib/own-annul209-public-predecessor-registry.mjs", "scripts/lib/own-m7-public-annulment208-source.mjs", "scripts/lib/own-annulment-ledger-trigger-profile.mjs", "scripts/lib/own-m7-public-annulment208209.mjs", "scripts/lib/own-annulment-atomic-preservation.mjs", "scripts/lib/own-m7-annul208209-atomic-source.mjs", "tests/own-annulment-ledger-trigger-profile.test.js"]);
export function projectZeroDifferenceRawSourceToParent(path,value){
 assert.equal(typeof path,'string');assert.ok(Buffer.isBuffer(value));
 if(!Object.hasOwn(rows,path))return value;
 const row=rows[path];let source=value;
 assert.equal(source.length,row.afterBytes,'ZERO_DIFFERENCE_CURRENT_RAW_BYTES');assert.equal(hash(source),row.afterSha256,'ZERO_DIFFERENCE_COMPLETE_CURRENT_RAW_SOURCE');
 for(const op of [...row.inverse].reverse()){
  const after=Buffer.from(op.afterBase64,'base64'),before=Buffer.from(op.beforeBase64,'base64');
  assert.deepEqual(source.subarray(op.afterOffset,op.afterOffset+after.length),after,'ZERO_DIFFERENCE_EXACT_REVIEWED_RAW_SPAN');
  source=Buffer.concat([source.subarray(0,op.afterOffset),before,source.subarray(op.afterOffset+after.length)]);
 }
 assert.equal(source.length,row.beforeBytes,'ZERO_DIFFERENCE_COMPLETE_PARENT_BYTES');assert.equal(hash(source),row.beforeSha256,'ZERO_DIFFERENCE_COMPLETE_PARENT_SHA');
 return source;
}
export function projectZeroDifferenceEngineRawSourceToParent(path,value){
 assert.equal(typeof path,'string');assert.ok(Buffer.isBuffer(value));
 if(!Object.hasOwn(engineRows,path))return value;
 const row=engineRows[path];let source=value;
 assert.equal(source.length,row.afterBytes,'ZERO_DIFFERENCE_ENGINE_CURRENT_RAW_BYTES');assert.equal(hash(source),row.afterSha256,'ZERO_DIFFERENCE_ENGINE_COMPLETE_CURRENT_RAW_SOURCE');
 for(const op of [...row.inverse].reverse()){
  const after=Buffer.from(op.afterBase64,'base64'),before=Buffer.from(op.beforeBase64,'base64');
  assert.deepEqual(source.subarray(op.afterOffset,op.afterOffset+after.length),after,'ZERO_DIFFERENCE_ENGINE_EXACT_REVIEWED_RAW_SPAN');
  source=Buffer.concat([source.subarray(0,op.afterOffset),before,source.subarray(op.afterOffset+after.length)]);
 }
 assert.equal(source.length,row.beforeBytes,'ZERO_DIFFERENCE_ENGINE_COMPLETE_PARENT_BYTES');assert.equal(hash(source),row.beforeSha256,'ZERO_DIFFERENCE_ENGINE_COMPLETE_PARENT_SHA');
 return source;
}
/** Outermost layer for every consumer: both row sets are disjoint, so the order of the two projections is immaterial. */
export function projectZeroDifferenceAllRawSourceToParent(path,value){
 return projectZeroDifferenceEngineRawSourceToParent(path,projectZeroDifferenceRawSourceToParent(path,value));
}
